package cart

import "errors"

var ErrItemNotFound = errors.New("item not found")

type Item struct {
	ID    string
	Name  string
	Price float64
}

type CartItem struct {
	Item
	Quantity int
}

type ShoppingCart struct {
	items map[string]*CartItem
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*CartItem),
	}
}

func (c *ShoppingCart) AddItem(item Item, quantity int) {
	if existing, ok := c.items[item.ID]; ok {
		existing.Quantity += quantity
		return
	}
	c.items[item.ID] = &CartItem{Item: item, Quantity: quantity}
}

func (c *ShoppingCart) RemoveItem(id string) error {
	if _, ok := c.items[id]; !ok {
		return ErrItemNotFound
	}
	delete(c.items, id)
	return nil
}

func (c *ShoppingCart) GetItem(id string) (*CartItem, error) {
	item, ok := c.items[id]
	if !ok {
		return nil, ErrItemNotFound
	}
	return item, nil
}

func (c *ShoppingCart) UpdateQuantity(id string, quantity int) error {
	item, ok := c.items[id]
	if !ok {
		return ErrItemNotFound
	}
	if quantity <= 0 {
		delete(c.items, id)
		return nil
	}
	item.Quantity = quantity
	return nil
}

func (c *ShoppingCart) Total() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) ItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*CartItem)
}

func (c *ShoppingCart) Items() []CartItem {
	result := make([]CartItem, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, *item)
	}
	return result
}
```

